CREATE DATABASE IF NOT EXISTS marketgo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE marketgo;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('buyer','seller','driver','admin') DEFAULT 'buyer',active TINYINT(1) DEFAULT 1);
CREATE TABLE tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,image_url VARCHAR(255),active TINYINT(1) DEFAULT 1,FOREIGN KEY(seller_id) REFERENCES users(id));
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,buyer_id BIGINT UNSIGNED NOT NULL,driver_id BIGINT UNSIGNED NULL,total DECIMAL(10,2) NOT NULL,status ENUM('pending','assigned','picked_up','delivered','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(buyer_id) REFERENCES users(id),FOREIGN KEY(driver_id) REFERENCES users(id));
